CREATE TABLE public.todo_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES public.organizations(id),todo_id uuid NOT NULL REFERENCES public.todos(id),object_path text NOT NULL UNIQUE,file_name text NOT NULL,size_bytes integer NOT NULL CHECK(size_bytes BETWEEN 1 AND 10485760),content_type text NOT NULL CHECK(content_type IN('image/jpeg','image/png','image/webp','application/pdf')),uploaded_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.todo_attachments TO authenticated; GRANT ALL ON public.todo_attachments TO service_role; ALTER TABLE public.todo_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY todo_attachment_read ON public.todo_attachments FOR SELECT TO authenticated USING(public.can_read_todo(todo_id));
CREATE OR REPLACE FUNCTION public.reserve_todo_attachment(_todo uuid,_file_name text,_size integer,_type text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t record; entry uuid:=gen_random_uuid(); path text; BEGIN SELECT * INTO t FROM public.todos WHERE id=_todo; IF NOT public.can_read_todo(_todo) OR t.archived_at IS NOT NULL THEN RAISE EXCEPTION 'forbidden'; END IF; IF length(_file_name) NOT BETWEEN 1 AND 200 OR _size NOT BETWEEN 1 AND 10485760 OR _type NOT IN('image/jpeg','image/png','image/webp','application/pdf') THEN RAISE EXCEPTION 'invalid_file'; END IF; path:=t.organization_id::text||'/'||t.id::text||'/'||entry::text; INSERT INTO public.todo_attachments(id,organization_id,todo_id,object_path,file_name,size_bytes,content_type,uploaded_by) VALUES(entry,t.organization_id,t.id,path,_file_name,_size,_type,auth.uid()); RETURN jsonb_build_object('id',entry,'path',path); END $$;
CREATE OR REPLACE FUNCTION public.todo_attachment_access(_path text,_write boolean) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.todo_attachments a JOIN public.todos t ON t.id=a.todo_id WHERE a.object_path=_path AND public.can_read_todo(a.todo_id) AND (NOT _write OR (a.uploaded_by=auth.uid() AND t.archived_at IS NULL))) $$;
CREATE OR REPLACE FUNCTION public.remove_todo_attachment(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a record; BEGIN SELECT * INTO a FROM public.todo_attachments WHERE id=_id FOR UPDATE; IF a.id IS NULL OR NOT public.can_read_todo(a.todo_id) OR (a.uploaded_by<>auth.uid() AND NOT public.is_org_admin(a.organization_id)) THEN RAISE EXCEPTION 'forbidden'; END IF; IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='todo-attachments' AND name=a.object_path) THEN RAISE EXCEPTION 'remove_file_first'; END IF; DELETE FROM public.todo_attachments WHERE id=a.id; END $$;
REVOKE ALL ON FUNCTION public.reserve_todo_attachment(uuid,text,integer,text),public.todo_attachment_access(text,boolean),public.remove_todo_attachment(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reserve_todo_attachment(uuid,text,integer,text),public.todo_attachment_access(text,boolean),public.remove_todo_attachment(uuid) TO authenticated;
CREATE POLICY todo_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='todo-attachments' AND public.todo_attachment_access(name,false));
CREATE POLICY todo_file_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='todo-attachments' AND public.todo_attachment_access(name,true));
CREATE POLICY todo_file_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='todo-attachments' AND EXISTS(SELECT 1 FROM public.todo_attachments a WHERE a.object_path=name AND public.can_read_todo(a.todo_id) AND (a.uploaded_by=auth.uid() OR public.is_org_admin(a.organization_id))));